"""
E1AP Protocol Messages Definition Module for PCAP Analysis.
This module provides predefined E1AP (E1 Application Protocol) message definitions and factory functions
for creating awaited messages used in PCAP file analysis.
The module defines AwaitedMessage objects that can be used to verify the presence and correctness of
specific E1AP protocol messages in network traffic captures.

:copyright:     Nokia Networks
:author:        Piotr Brzezicki, Mateusz Potoniec
:maintainer:    Piotr Brzezicki, Mateusz Potoniec
:contact:       piotr.brzezicki@nokia.com, mateusz.potoniec@nokia.com

Usage:
    from taf.rfrl.utilities.parsers.pcap_checker import Checker
    from taf.rfrl.utilities.parsers.pcap_checker.utils import PcapProvider
    from taf.rfrl.utilities.parsers.pcap_checker.messages import e1ap_messages

    awaited_messages = [
        e1ap_messages.BEARER_CONTEXT_SETUP_REQUEST,
        e1ap_messages.BEARER_CONTEXT_SETUP_RESPONSE,
        e1ap_messages.BEARER_CONTEXT_MODIFICATION_REQUEST,
        e1ap_messages.BEARER_CONTEXT_MODIFICATION_RESPONSE
    ]

    forbidden_messages = []

    pcap_provider = PcapProvider()
    checker = Checker(pcap_provider=pcap_provider)
    checker.expect_flow(
        pcap_file=pcap_file,
        display_filter='e1ap',
        awaited_messages=awaited_messages,
        forbidden_messages=forbidden_messages
    )
"""


from taf.rfrl.utilities.parsers.pcap_checker.checker import AwaitedMessage
from taf.rfrl.utilities.parsers.pcap_checker.inspectors import HasInspector


BEARER_CONTEXT_SETUP_REQUEST = AwaitedMessage(
    name='BearerContextSetupRequest',
    find_by=[HasInspector('e1ap.BearerContextSetupRequest_element')],
    verify_by=[],
)


BEARER_CONTEXT_SETUP_RESPONSE = AwaitedMessage(
    name='BearerContextSetupResponse',
    find_by=[HasInspector('e1ap.BearerContextSetupResponse_element')],
    verify_by=[],
)


BEARER_CONTEXT_MODIFICATION_REQUEST = AwaitedMessage(
    name='BearerContextModificationRequest',
    find_by=[HasInspector('e1ap.BearerContextModificationRequest_element')],
    verify_by=[],
)


BEARER_CONTEXT_MODIFICATION_RESPONSE = AwaitedMessage(
    name='BearerContextModificationResponse',
    find_by=[HasInspector('e1ap.BearerContextModificationResponse_element')],
    verify_by=[],
)


BEARER_CONTEXT_RELEASE_COMMAND_RADIO_NETWORK_NORMAL_RELEASE = AwaitedMessage(
    name='BearerContextReleaseCommand',
    find_by=[HasInspector('e1ap.BearerContextReleaseCommand_element')],
    verify_by=[HasInspector('e1ap.radioNetwork', '20')],
)


BEARER_CONTEXT_RELEASE_COMPLETE = AwaitedMessage(
    name='BearerContextReleaseComplete',
    find_by=[HasInspector('e1ap.BearerContextReleaseComplete_element')],
    verify_by=[],
)
